//! `Frame::norm_points` normalises a set of points as C's `astNormPoints`
//! does through each class's `astNormalPoints`: a SkyFrame asked for
//! contiguous values keeps its longitudes on one side of the widest gap
//! between them, a CmpFrame hands each component its own axes, and a
//! FrameSet its current Frame. `Region::region_mesh` normalises the
//! boundary mesh the same way, as `astGetRegionMesh` does.
//!
//! `norm_points_oracle/cases.rs` is generated by
//! `tools/oracle_fixtures/norm_points_probe.c`.

// Generated; formatted by its generator rather than rustfmt.
#[rustfmt::skip]
#[path = "norm_points_oracle/cases.rs"]
mod cases;

use ast_core::coords::PointSet;
use ast_core::frames::{BasicFrameBuilder, CmpFrame, Frame, FrameSet, SkyFrame};
use ast_core::regions::{CircleBuilder, Region};

const D2R: f64 = std::f64::consts::PI / 180.0;

/// The probe's points, longitude on axis `lon_axis + 1`, with a third
/// value of 7.5 when `ncoord` is 3.
fn points(ncoord: usize, lon_axis: usize) -> PointSet {
    let rows: Vec<Vec<f64>> = cases::LON
        .iter()
        .zip(cases::LAT)
        .map(|(&lon, lat)| {
            let mut row = vec![0.0; ncoord];
            row[lon_axis] = lon * D2R;
            row[1 - lon_axis] = lat * D2R;
            if ncoord == 3 {
                row[2] = 7.5;
            }
            row
        })
        .collect();
    PointSet::from_rows(rows)
}

fn rows(ps: &PointSet) -> Vec<Vec<f64>> {
    (0..ps.npoint()).map(|i| ps.point(i).to_vec()).collect()
}

#[test]
fn norm_points_follows_the_c_library() {
    let sky = SkyFrame::unset_system();
    let mut swapped = sky.clone();
    swapped.perm_axes(&[2, 1]).unwrap();
    let cmp = CmpFrame::new(
        Box::new(sky.clone()),
        Box::new(BasicFrameBuilder::new(1).build().unwrap()),
    );
    let fs = FrameSet::new(Box::new(sky.clone()));

    let got: Vec<(&str, PointSet)> = vec![
        ("sky", sky.norm_points(&points(2, 0), false).unwrap()),
        ("sky_contig", sky.norm_points(&points(2, 0), true).unwrap()),
        (
            "sky_swapped_contig",
            swapped.norm_points(&points(2, 1), true).unwrap(),
        ),
        (
            "cmpframe_contig",
            cmp.norm_points(&points(3, 0), true).unwrap(),
        ),
        (
            "frameset_contig",
            fs.norm_points(&points(2, 0), true).unwrap(),
        ),
    ];

    let mut failures = Vec::new();
    assert_eq!(
        got.len(),
        cases::CASES.len(),
        "the test runs every case the C probe recorded"
    );
    for ((name, ps), &(want_name, want)) in got.iter().zip(cases::CASES) {
        assert_eq!(*name, want_name, "the test runs the probe's cases");
        let want: Vec<Vec<f64>> = want.iter().map(|r| r.to_vec()).collect();
        if rows(ps) != want {
            failures.push(format!("{name}: got {:?}, C gives {want:?}", rows(ps)));
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}

#[test]
fn a_circle_mesh_is_normalised_as_c_does() {
    let circle = CircleBuilder::new(SkyFrame::unset_system(), vec![0.0, 0.0])
        .unwrap()
        .radius(5.0 * D2R)
        .build()
        .unwrap();
    let mesh = rows(&circle.region_mesh().unwrap());
    assert_eq!(mesh.len(), cases::CIRCLE_MESH.len(), "number of points");
    for (i, (got, want)) in mesh.iter().zip(cases::CIRCLE_MESH).enumerate() {
        crate::common::assert_c_values(got, want, &format!("point {i}"));
    }
}
